function drawCloud(cx, cy, scale) {
  ctx.fillStyle = '#fff';
  ctx.beginPath();
  const r = 15 * scale;
  ctx.arc(cx, cy, r, Math.PI * 0.5, Math.PI * 1.5);
  ctx.arc(cx + r, cy - r, r, Math.PI * 1, Math.PI * 1.85);
  ctx.arc(cx + r * 2, cy - r, r, Math.PI * 1.15, Math.PI * 1.85);
